insert into platform_modules(code,title,is_active) values ('35-page-block-editor','ویرایشگر بلوک‌های صفحات',true) on conflict(code) do update set title=excluded.title,is_active=true;
insert into module_field_definitions(module_id,field_key,title,field_type,required,sort_order,options)
insert into module_actions(module_id,action_code,title,permission) select m.id,v.a,v.t,v.p from platform_modules m cross join (values
('read','مشاهده بلوک‌ها','modules:35-page-block-editor:read'),('write','ساخت و ویرایش بلوک','modules:35-page-block-editor:write'),('delete','حذف بلوک','modules:35-page-block-editor:delete'),('publish','فعال‌سازی بلوک','modules:35-page-block-editor:publish'),('disable','غیرفعال‌سازی بلوک','modules:35-page-block-editor:disable'),('duplicate','تکثیر بلوک','modules:35-page-block-editor:duplicate'),('reorder','تنظیم ترتیب بلوک','modules:35-page-block-editor:reorder')) v(a,t,p) where m.code='35-page-block-editor' on conflict(module_id,action_code) do update set title=excluded.title,permission=excluded.permission;