select m.id,v.k,v.t,v.ft,v.r,v.s,v.o::jsonb from platform_modules m cross join (values
('block-code','کد بلوک','text',true,10,'{}'),('page-code','کد صفحه','text',true,20,'{}'),('block-title','عنوان بلوک','text',true,30,'{}'),('block-type','نوع بلوک','select',true,40,'{"options":["عنوان و متن","تصویر","گالری","کارت","آمار","جدول","فرم","دکمه","فراخوان اقدام","تب‌ها","آکاردئون","HTML","فاصله‌گذار","سفارشی"]}'),('zone','ناحیه صفحه','select',true,50,'{"options":["هدر","محتوای اصلی","ستون راست","ستون چپ","بین محتوا","سایدبار","فوتر"]}'),('order-index','ترتیب نمایش','number',true,60,'{}'),('content-reference','مرجع محتوا','text',false,70,'{}'),('visibility','نمایش','select',true,80,'{"options":["نمایش داده شود","مخفی","فقط موبایل","فقط دسکتاپ"]}'),('responsive-mode','رفتار ریسپانسیو','select',true,90,'{"options":["خودکار","فشرده در موبایل","حفظ ساختار","مخفی در موبایل"]}'),('status','وضعیت','select',true,100,'{"options":["پیش‌نویس","فعال","غیرفعال","آرشیو شده"]}'),('version','نسخه','number',true,110,'{}'),('settings-reference','مرجع تنظیمات','text',false,120,'{}'),('notes','یادداشت','textarea',false,130,'{}')
) v(k,t,ft,r,s,o) where m.code='35-page-block-editor' on conflict(module_id,field_key) do update set title=excluded.title,field_type=excluded.field_type,required=excluded.required,sort_order=excluded.sort_order,options=excluded.options;
